import { snippetAssetProjectionToValue } from './snippet-asset.model';
import { ComponentFixture, TestBed } from '@angular/core/testing';
import {
  InteractionMocks,
  RepositoryMock,
  allow,
  configureFeatureTesting,
  createWithoutTemplate,
  internals,
  mockRepository,
  mockTick,
  moduleCompiles,
} from 'app/shared/testing/feature-testing';

describe('snippetAssetProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    snippet: { $ref: 'ref-snippet' },
    code: 'value-code',
    type: 'value-type',
    content: 'value-content',
    enabled: 'value-enabled',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(snippetAssetProjectionToValue(null)).toBeNull();
    expect(snippetAssetProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(snippetAssetProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      snippet: () => ({ uid: 'ref-snippet' }),
      code: 'value-code',
      type: 'value-type',
      content: 'value-content',
      enabled: 'value-enabled',
      version: 'value-version',
    } as any;
    expect(snippetAssetProjectionToValue(projection)).toEqual(value);
  });
});
